def _fmt_path(project_slug: str, workflow_name: str) -> str:
    # Preserve slashes in project slug as per allowReserved while percent-encoding other characters
    # Workflow name typically simple, but still encode safely (spaces, etc.) without encoding slashes
    ps = urllib.parse.quote(project_slug, safe="/:@-._~")
    wn = urllib.parse.quote(workflow_name, safe="-._~")
    return _ENDPOINT.replace("{project-slug}", ps).replace("{workflow-name}", wn)


